const moveBackupSchedules = `-- name: MoveBackupSchedules :execrows
UPDATE backup_schedules SET service_id = $2, updated_at = now() WHERE service_id = $1
`

type MoveBackupSchedulesParams struct {
	ServiceID   uuid.UUID `json:"serviceId"`
	ServiceID_2 uuid.UUID `json:"serviceId2"`
}

func (q *Queries) MoveBackupSchedules(ctx context.Context, arg MoveBackupSchedulesParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveBackupSchedules, arg.ServiceID, arg.ServiceID_2)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const observeDatabaseReplica = `-- name: ObserveDatabaseReplica :exec
UPDATE database_replicas
SET receive_lsn = COALESCE($1, receive_lsn), replay_lsn = COALESCE($2, replay_lsn),
    lag_bytes = COALESCE($3, lag_bytes), replay_lag_ms = COALESCE($4, replay_lag_ms),
    wal_status = COALESCE($5, wal_status), retained_bytes = COALESCE($6, retained_bytes),
    observed_at = $7,
    last_streaming_at = CASE WHEN $8::boolean THEN $7 ELSE last_streaming_at END
WHERE service_id = $9
`

type ObserveDatabaseReplicaParams struct {
	ReceiveLsn    *string    `json:"receiveLsn"`
	ReplayLsn     *string    `json:"replayLsn"`
	LagBytes      *int64     `json:"lagBytes"`
	ReplayLagMs   *int64     `json:"replayLagMs"`
	WalStatus     *string    `json:"walStatus"`
	RetainedBytes *int64     `json:"retainedBytes"`
	ObservedAt    *time.Time `json:"observedAt"`
	Healthy       bool       `json:"healthy"`
	ServiceID     uuid.UUID  `json:"serviceId"`
}

// Merges one side's observation (primary or replica): a side that does not know a
// value leaves it. updated_at is the saga clock and is not touched.
func (q *Queries) ObserveDatabaseReplica(ctx context.Context, arg ObserveDatabaseReplicaParams) error {
	_, err := q.db.Exec(ctx, observeDatabaseReplica,
		arg.ReceiveLsn,
		arg.ReplayLsn,
		arg.LagBytes,
		arg.ReplayLagMs,
		arg.WalStatus,
		arg.RetainedBytes,
		arg.ObservedAt,
		arg.Healthy,
		arg.ServiceID,
	)
	return err
}

